      "title": "Informacijos sąlyga (BDAR)",
      "intro": "Vadovaujantis 2008 m. 2016-04-27 Bendrojo asmens duomenų apsaugos reglamento (OL EU L 119, 2016-05-04) 13 p., informuoju, kad:",
